(()=>{let ctx,timer,on=false,step=0;const melody=[69,72,76,74,72,67,69,0,65,69,72,71,69,67,64,0,69,72,77,76,74,72,71,67,65,69,72,76,74,71,69,0];const bass=[45,45,41,41,48,48,43,43];function tone(n,start,length,type,gain){if(!n)return;let o=ctx.createOscillator(),v=ctx.createGain();o.type=type;o.frequency.value=440*2**((n-69)/12);v.gain.setValueAtTime(0,start);v.gain.linearRampToValueAtTime(gain,start+.012);v.gain.exponentialRampToValueAtTime(.0001,start+length);o.connect(v);v.connect(ctx.destination);o.start(start);o.stop(start+length+.02)}window.GameAudio={toggle(){on=!on;if(on){ctx??=new(window.AudioContext||window.webkitAudioContext)();ctx.resume();step=0;timer=setInterval(()=>{let t=ctx.currentTime;tone(melody[step%32],t,.26,'triangle',.055);if(step%2===0)tone(bass[Math.floor(step/4)%8],t,.49,'triangle',.04);step++},290)}else clearInterval(timer);return on},effect(kind){if(!on)return;let n=kind==='hit'?44:kind==='open'?76:57;tone(n,ctx.currentTime,.08,'square',.014)}}})();
